import { createClient } from '@/lib/supabase/server'
import { Package, Users, AlertTriangle, ArrowRightLeft, DollarSign } from 'lucide-react'
import { StatCard } from '@/components/dashboard/StatCard'
import { AiInsightsCard } from '@/components/dashboard/AiInsightsCard'
import { RevenueChart } from '@/components/dashboard/RevenueChart'
import { RecentActivityList } from '@/components/dashboard/RecentActivityList'
import { getDashboardMetrics, getRevenueChartData } from '@/app/actions/dashboard'
import { getWarehouseCookie } from '@/app/actions/warehouse-cookie'

export const dynamic = 'force-dynamic'

export default async function DashboardPage() {
    const supabase = await createClient()

    // Get current user's organization_id from their profile
    const { data: { user } } = await supabase.auth.getUser()

    let organizationId: string | null = null

    if (user) {
        const { data: profile } = await supabase
            .from('profiles')
            .select('organization_id')
            .eq('id', user.id)
            .single()

        organizationId = profile?.organization_id || null
    }

    // --- FETCH DATA ---
    const warehouseId = await getWarehouseCookie()

    // 1. Metrics from optimized Action
    const metrics = await getDashboardMetrics()
    
    // 2. Chart Data
    const chartData = await getRevenueChartData('7d')

    // 3. Recent Activity (Movements)
    let recentMovements: unknown[] = []
    
    if (organizationId) {
        let query = supabase
            .from('stock_movements')
            .select('*, item:items(name)')
            .eq('organization_id', organizationId)
            .order('created_at', { ascending: false })
            .limit(6)
        
        if (warehouseId) {
            query = query.eq('location_id', warehouseId)
        }

        const { data } = await query
        recentMovements = data || []
    }

     // --- AI Forecast Data Fetching ---
    const { getAiInsights } = await import('@/app/actions/ai')
    const insights = await getAiInsights()

    return (
        <div className="space-y-8 p-2 min-h-screen">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-white">Dashboard</h1>
                    <p className="text-sm text-slate-400 mt-1">Real-time overview of your operations</p>
                </div>
            </div>

            {/* AI Insights Section */}
            <AiInsightsCard insights={insights} />

            {/* Stats Grid */}
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                <StatCard
                    title="Total Items"
                    value={metrics?.itemsCount || 0}
                    icon={<Package className="h-6 w-6" />}
                    color="blue"
                    delay={0.1}
                />
                <StatCard
                    title="Stock Value"
                    value={`₹${(metrics?.totalStockValue || 0).toLocaleString()}`}
                    icon={<DollarSign className="h-6 w-6" />}
                    color="emerald"
                    delay={0.2}
                />
                <StatCard
                    title="Low Stock"
                    value={metrics?.lowStockCount || 0}
                    icon={<AlertTriangle className="h-6 w-6" />}
                    color="cyan"
                    delay={0.3}
                    trend={metrics?.lowStockCount ? { value: metrics.lowStockCount, label: 'Items', positive: false } : undefined}
                />
                <StatCard
                    title="Recent Activity"
                    value={recentMovements?.length || 0}
                    icon={<ArrowRightLeft className="h-6 w-6" />}
                    color="sky"
                    delay={0.4}
                    description="Movements in last 24h"
                />
            </div>

            {/* Main Content Grid */}
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-7">
                {/* Revenue Chart */}
                <RevenueChart data={chartData} />
                
                {/* Recent Activity List */}
                <RecentActivityList activities={recentMovements} />
            </div>
        </div>
    )
}

'use client'

import { Check, X, Zap, Loader2, Sparkles } from 'lucide-react'
import { TrialOfferDialog } from '@/components/subscription/TrialOfferDialog'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { useState, useEffect } from 'react'
import Script from 'next/script'
import { toast } from 'sonner'
import { useRouter, useSearchParams } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'

declare global {
    interface Window {
        Cashfree: unknown;
    }
}

export default function PricingPage() {
    const [loading, setLoading] = useState(false)
    const [currentPlan, setCurrentPlan] = useState<string>('FREE')
    const [isLoadingPlan, setIsLoadingPlan] = useState(true)
    const _router = useRouter()
    const searchParams = useSearchParams()
    // const searchParams = typeof window !== 'undefined' ? new URLSearchParams(window.location.search) : null // BROKEN: Causes infinite loop
    const [trialUsed, setTrialUsed] = useState(false)
    const [subStatus, setSubStatus] = useState<string>('')
    const [orgId, setOrgId] = useState<string>('')
    const [showTrialDialog, setShowTrialDialog] = useState(false)
    const supabase = createClient()

    // Verify Payment Effect
    useEffect(() => {
        const orderId = searchParams?.get('order_id')
        if (orderId) {
            verifyCashfreePayment(orderId)
        }
    }, [searchParams])

    const verifyCashfreePayment = async (orderId: string) => {
        setLoading(true)
        try {
            const res = await fetch('/api/cashfree/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ orderId })
            })
            const data = await res.json()

            if (data.success) {
                toast.success("Payment Successful! Welcome to Pro.")
                // Clean URL
                window.history.replaceState({}, document.title, window.location.pathname)
                // Force Reload
                window.location.reload()
            } else {
                toast.error(data.error || "Payment verification failed")
            }
        } catch (_error) {
            toast.error("Verification failed or Payment was cancelled")
        } finally {
            // Clean URL even on failure to prevent loop/retry on refresh
            window.history.replaceState({}, document.title, window.location.pathname)
            setLoading(false)
        }
    }

    // Load Plan Details
    useEffect(() => {
        async function fetchPlan() {
            const { data: { user } } = await supabase.auth.getUser()
            if (user) {
                const { data: profile } = await supabase
                    .from('profiles')
                    .select('organization_id, organizations(plan_type, trial_used, subscription_status)')
                    .eq('id', user.id)
                    .single()

                // @ts-expect-error -- third-party type mismatch
                if (profile?.organizations?.plan_type) {
                    // @ts-expect-error -- third-party type mismatch
                    setCurrentPlan(profile.organizations.plan_type)
                    // @ts-expect-error -- third-party type mismatch
                    setTrialUsed(profile.organizations.trial_used || false)
                    // @ts-expect-error -- third-party type mismatch
                    setSubStatus(profile.organizations.subscription_status || '')
                }
                if (profile?.organization_id) setOrgId(profile.organization_id)
            }
            setIsLoadingPlan(false)
        }
        fetchPlan()
    }, [supabase])

    // ... existing plan fetch effect ...

    const handlePayment = async () => {
        setLoading(true)
        try {
            // 1. Create Order & Get Session
            const res = await fetch('/api/cashfree/create-order', {
                method: 'POST'
            })
            const data = await res.json()

            if (data.error) {
                toast.error(data.error)
                setLoading(false)
                return
            }

            // 2. Initialize Cashfree SDK
            const cashfree = new window.Cashfree({
                mode: process.env.NEXT_PUBLIC_CASHFREE_ENV === 'PRODUCTION' ? "production" : "sandbox"
            });

            // 3. Open Checkout
            cashfree.checkout({
                paymentSessionId: data.paymentSessionId,
                returnUrl: `${window.location.origin}/pricing?order_id=${data.orderId}`
            });

        } catch (error) {
            console.error("Payment Error:", error)
            toast.error("Failed to initiate payment")
            setLoading(false)
        }
    }

    if (isLoadingPlan) {
        return <div className="flex h-full items-center justify-center"><Loader2 className="h-8 w-8 animate-spin" /></div>
    }

    return (
        <div className="flex-1 space-y-8 p-8 pt-6">
            <Script
                id="cashfree-js"
                src="https://sdk.cashfree.com/js/v3/cashfree.js"
                strategy="lazyOnload"
            />

            <div className="flex flex-col items-center justify-center text-center gap-4 mb-16">
                <h2 className="text-4xl md:text-5xl font-extrabold tracking-tight text-white">
                    Simple, Transparent Pricing
                </h2>
                <p className="text-lg text-slate-400 max-w-2xl">
                    Choose the plan that's right for your business. Upgrade anytime as you grow.
                </p>
            </div>

            <div className="grid grid-cols-1 gap-8 lg:grid-cols-3 lg:gap-10 max-w-7xl mx-auto">
                {/* Free Plan */}
                <div className={cn(
                    "relative flex flex-col rounded-3xl border border-white/5 bg-white/5 backdrop-blur-sm p-8 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:bg-white/10 hover:shadow-indigo-500/10",
                    currentPlan === 'FREE' ? "ring-1 ring-white/10" : ""
                )}>
                    <div className="mb-8">
                        <h3 className="text-xl font-medium text-slate-200">Starter</h3>
                        <p className="text-sm text-slate-400 mt-2">Perfect for small shops just starting out.</p>
                        <div className="mt-6 flex items-baseline">
                            <span className="text-4xl font-bold text-white">₹0</span>
                            <span className="ml-1 text-sm font-medium text-slate-500">/mo</span>
                        </div>
                    </div>
                    <ul className="mb-8 space-y-4 flex-1">
                        {[
                            'Single User',
                            'Basic Inventory Tracking',
                            'Basic Reports (KPIs & trends)',
                            'Sales & Invoices 🧾',
                            'Low Stock Table'
                        ].map((feature) => (
                            <li key={feature} className="flex items-center gap-3">
                                <div className="rounded-full bg-slate-800 p-1">
                                    <Check className="h-3.5 w-3.5 text-slate-400" />
                                </div>
                                <span className="text-sm text-slate-300">{feature}</span>
                            </li>
                        ))}
                        <li className="flex items-center gap-3 text-slate-500">
                            <div className="rounded-full bg-slate-800/50 p-1">
                                <X className="h-3.5 w-3.5" />
                            </div>
                            <span className="text-sm">No Financial Analytics</span>
                        </li>
                        <li className="flex items-center gap-3 text-slate-500">
                            <div className="rounded-full bg-slate-800/50 p-1">
                                <X className="h-3.5 w-3.5" />
                            </div>
                            <span className="text-sm">No Barcode Scanning</span>
                        </li>
                    </ul>
                    <Button
                        className="w-full bg-white/5 hover:bg-white/10 text-slate-300 border-0 rounded-xl transition-all duration-200"
                        disabled
                    >
                        {currentPlan === 'FREE' ? 'Current Plan' : 'Downgrade'}
                    </Button>
                </div>

                {/* Pro Plan - Highlighted */}
                <div className={cn(
                    "relative flex flex-col rounded-3xl border border-indigo-500/30 bg-indigo-900/10 backdrop-blur-md p-8 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:shadow-indigo-500/20 ring-1 ring-indigo-500/50 scale-105 z-10",
                    currentPlan === 'PRO' ? "ring-indigo-500" : ""
                )}>
                    <div className="absolute -top-4 left-0 right-0 mx-auto w-fit rounded-full bg-indigo-600 px-4 py-1 text-xs font-medium text-white shadow-lg shadow-indigo-500/40 flex items-center gap-1">
                        MOST POPULAR
                    </div>

                    <div className="mb-8">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-xl font-medium text-indigo-300 flex items-center gap-2">
                                    Pro <Zap className="h-4 w-4 text-yellow-400 fill-yellow-400" />
                                </h3>
                                <p className="text-sm text-indigo-200/60 mt-2">For growing businesses that need control.</p>
                            </div>
                            {currentPlan === 'PRO' && subStatus === 'TRIALING' && (
                                <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-orange-500/20 text-orange-400 border border-orange-500/30">
                                    Trial Active
                                </span>
                            )}
                        </div>
                        <div className="mt-6 flex items-baseline">
                            <span className="text-5xl font-bold text-white">₹399</span>
                            <span className="ml-1 text-sm font-medium text-indigo-200/60">/mo</span>
                        </div>
                    </div>

                    <ul className="mb-8 space-y-4 flex-1">
                        {[
                            { text: '5 Team Members', icon: Check },
                            { text: 'Advanced Financial Analytics 💰', icon: Check },
                            { text: 'Barcode Scanning App 📱', icon: Check },
                            { text: 'Stock Movement Logs (Audit Trail) 📋', icon: Check },
                            { text: 'Warehouse Transfers 🚚', icon: Check },
                            { text: 'Low Stock Email Alerts', icon: Check },
                            { text: 'AI Stock Predictions 🤖', icon: Check },
                            { text: 'Bulk CSV Import/Export 📤', icon: Check },
                        ].map((item) => (
                            <li key={item.text} className="flex items-center gap-3">
                                <div className="rounded-full bg-indigo-500/20 p-1">
                                    <item.icon className="h-3.5 w-3.5 text-indigo-400" />
                                </div>
                                <span className="text-sm text-white font-medium">{item.text}</span>
                            </li>
                        ))}
                    </ul>

                    <div className="flex flex-col gap-3">
                        {currentPlan === 'PRO' && subStatus !== 'TRIALING' ? (
                            <Button className="w-full bg-emerald-500/20 text-emerald-400 cursor-default hover:bg-emerald-500/20 border border-emerald-500/30 rounded-xl" disabled>
                                <Check className="mr-2 h-4 w-4" /> Current Plan
                            </Button>
                        ) : (
                            <>
                                {currentPlan === 'PRO' && subStatus === 'TRIALING' && (
                                    <div className="w-full mb-3 p-3 bg-indigo-500/10 border border-indigo-500/20 rounded-xl text-center">
                                        <p className="text-sm font-medium text-indigo-400">
                                            ⚠️ Trial Mode Active
                                        </p>
                                        <p className="text-xs text-indigo-300/80 mt-1">
                                            Upgrade now to keep your data & features forever.
                                        </p>
                                    </div>
                                )}

                                {currentPlan === 'FREE' && !trialUsed && (
                                    <Button
                                        className="w-full bg-orange-600 hover:bg-orange-700 text-white border-0 rounded-xl shadow-lg shadow-orange-500/25 transition-all duration-300 font-bold"
                                        onClick={() => {
                                            toast.info("Loading offer details...")
                                            setShowTrialDialog(true)
                                        }}
                                    >
                                        <Sparkles className="mr-2 h-4 w-4 fill-white" />
                                        Start 5-Day Free Trial
                                    </Button>
                                )}

                                <Button
                                    onClick={handlePayment}
                                    disabled={loading}
                                    className="w-full bg-indigo-600 hover:bg-indigo-700 text-white border-0 rounded-xl shadow-lg shadow-indigo-500/25 transition-all duration-300"
                                >
                                    {loading ? (
                                        <>
                                            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                            Processing...
                                        </>
                                    ) : (
                                        <>
                                            <Zap className="mr-2 h-4 w-4 fill-white" />
                                            Upgrade to Pro
                                        </>
                                    )}
                                </Button>
                            </>
                        )}
                    </div>
                </div>

                {/* Enterprise Plan */}
                <div className="relative flex flex-col rounded-3xl border border-white/5 bg-white/5 backdrop-blur-sm p-8 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:bg-white/10 hover:shadow-indigo-500/10">
                    <div className="mb-8">
                        <h3 className="text-xl font-medium text-slate-200">Enterprise</h3>
                        <p className="text-sm text-slate-400 mt-2">Custom solutions for large organizations.</p>
                        <div className="mt-6 flex items-baseline">
                            <span className="text-4xl font-bold text-white">Custom</span>
                        </div>
                    </div>
                    <ul className="mb-8 space-y-4 flex-1">
                        {[
                            'Unlimited Users & Roles',
                            'Custom Feature Development',
                            'Dedicated Account Manager',
                            'Custom Integrations (ERP/SAP)',
                            'On-premise Deployment',
                            '24/7 Priority Support'
                        ].map((feature) => (
                            <li key={feature} className="flex items-center gap-3">
                                <div className="rounded-full bg-purple-500/20 p-1">
                                    <Check className="h-3.5 w-3.5 text-purple-400" />
                                </div>
                                <span className="text-sm text-slate-300">{feature}</span>
                            </li>
                        ))}
                    </ul>
                    <Button
                        className="w-full bg-white/10 hover:bg-white/20 text-white border-0 rounded-xl transition-all duration-200"
                        asChild
                    >
                        <a href="mailto:sales@inventory.com?subject=Enterprise%20Plan%20Inquiry">Contact Sales</a>
                    </Button>
                </div>
            </div>

            {/* Trust Signals */}
            <div className="mt-12 text-center">
                <p className="text-muted-foreground text-sm">
                    Trusted by 500+ businesses worldwide.
                    <br />
                    Secure payments via Cashfree Payments. Cancel anytime.
                </p>
            </div>
            <TrialOfferDialog
                open={showTrialDialog}
                onOpenChange={setShowTrialDialog}
                organizationId={orgId}
                trialUsed={trialUsed}
                planType={currentPlan}
            />
        </div >
    )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { getWarehouseCookie } from './warehouse-cookie'
import { addDays, format, subDays, startOfDay, endOfDay } from 'date-fns'

export interface DashboardMetric {
    label: string
    value: number
    change?: number
    trend?: 'up' | 'down' | 'neutral'
}

export type ChartData = {
    date: string
    revenue: number
    orders: number
}[]

export async function getDashboardMetrics() {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return null

    // Get Org ID
    const { data: profile } = await supabase.from('profiles').select('organization_id').eq('id', user.id).single()
    const organizationId = profile?.organization_id

    if (!organizationId) return null

    const warehouseId = await getWarehouseCookie()

    // 1. Fetch Item Stats
    let itemsCount = 0
    let lowStockCount = 0
    let totalStockValue = 0

    if (warehouseId) {
        // Local Scope
         const { data: stockItems } = await supabase
            .from('item_stock')
            .select(`
                quantity,
                item:items (id, min_stock, price)
            `)
            .eq('location_id', warehouseId)
        
        if (stockItems) {
            itemsCount = stockItems.length
            // @ts-expect-error -- third-party type mismatch
            lowStockCount = stockItems.filter(i => i.quantity < (i.item?.min_stock || 0)).length
            // @ts-expect-error -- third-party type mismatch
            totalStockValue = stockItems.reduce((acc, curr) => acc + (curr.quantity * (curr.item?.price || 0)), 0)
        }

    } else {
        // Global Scope
        const { data: allItems } = await supabase
            .from('items')
            .select('current_stock, min_stock, price')
            .eq('organization_id', organizationId)
        
        if (allItems) {
            itemsCount = allItems.length
            lowStockCount = allItems.filter(i => (i.current_stock || 0) < (i.min_stock || 0)).length
             totalStockValue = allItems.reduce((acc, curr) => acc + ((curr.current_stock || 0) * (curr.price || 0)), 0)
        }
    }

    return {
        itemsCount,
        lowStockCount,
        totalStockValue,
    }
}

export async function getRevenueChartData(period: '7d' | '30d' = '7d'): Promise<ChartData> {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return []

    const { data: profile } = await supabase.from('profiles').select('organization_id').eq('id', user.id).single()
    const organizationId = profile?.organization_id
    if (!organizationId) return []

    const days = period === '30d' ? 30 : 7
    const startDate = subDays(new Date(), days)

    // Fetch invoices in range
    const { data: invoices } = await supabase
        .from('invoices')
        .select(`created_at, total_amount`)
        .eq('organization_id', organizationId)
        .gte('created_at', startDate.toISOString())
        .order('created_at', { ascending: true })
    
    // Group by day
    const groupedData = new Map<string, { revenue: number, orders: number }>()

    // Initialize all days
    for (let i = 0; i <= days; i++) {
        const d = addDays(startDate, i)
        const dateKey = format(d, 'MMM dd')
        groupedData.set(dateKey, { revenue: 0, orders: 0 })
    }

    // Populate actuals
    invoices?.forEach(inv => {
        const dateKey = format(new Date(inv.created_at), 'MMM dd')
        const current = groupedData.get(dateKey) || { revenue: 0, orders: 0 }
        groupedData.set(dateKey, {
            revenue: current.revenue + (inv.total_amount || 0),
            orders: current.orders + 1
        })
    })

    return Array.from(groupedData.entries()).map(([date, data]) => ({
        date,
        revenue: data.revenue,
        orders: data.orders
    }))
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'

export async function getLocations(organizationId?: string) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return []

    const { data: profile } = await supabase
        .from('profiles')
        .select('organization_id')
        .eq('id', user.id)
        .single()

    if (!profile?.organization_id) return []
    const targetOrgId = profile.organization_id

    const { data: locations, error } = await supabase
        .from('locations')
        .select('*')
        .eq('organization_id', targetOrgId)
        .order('is_default', { ascending: false })
        .order('created_at', { ascending: true })

    if (error) {
        console.error('Error fetching locations:', error)
        return []
    }

    return locations
}

export async function createLocation(data: { name: string; address?: string; organizationId?: string }) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    const { data: profile } = await supabase
        .from('profiles')
        .select('organization_id, role, is_super_admin')
        .eq('id', user.id)
        .single()

    if (!profile?.organization_id) return { error: 'No organization found' }
    if (profile.role !== 'ADMIN' && !profile.is_super_admin) {
        return { error: 'Only Admins can create warehouses' }
    }

    const orgId = profile.organization_id

    // 1. Get current plan & limit
    const { data: org, error: orgError } = await supabase
        .from('organizations')
        .select('plan_type, subscription_status')
        .eq('id', orgId)
        .single()

    if (orgError) return { error: "Failed to fetch organization details" }

    // 2. Count existing locations
    const { count, error: countError } = await supabase
        .from('locations')
        .select('*', { count: 'exact', head: true })
        .eq('organization_id', orgId)

    if (countError) return { error: "Failed to count locations" }

    // 3. Enforce Limit (Pro = 2) 
    const MAX_LOCATIONS = 2
    if (org.plan_type !== 'ENTERPRISE' && (count || 0) >= MAX_LOCATIONS) {
        return { error: `Pro Plan is limited to ${MAX_LOCATIONS} Warehouses. Upgrade to Enterprise for unlimited.` }
    }

    const { error } = await supabase
        .from('locations')
        .insert({
            name: data.name,
            address: data.address,
            organization_id: orgId
        })

    if (error) return { error: error.message }

    revalidatePath('/settings')
    revalidatePath('/warehouses')
    return { success: true }
}

export async function updateLocation(locationId: string, data: { name?: string; address?: string }) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    const { data: profile } = await supabase
        .from('profiles')
        .select('organization_id, role, is_super_admin')
        .eq('id', user.id)
        .single()

    if (!profile?.organization_id) return { error: 'Unauthorized' }
    if (profile.role !== 'ADMIN' && !profile.is_super_admin) {
        return { error: 'Only Admins can update warehouses' }
    }

    const { error } = await supabase
        .from('locations')
        .update(data)
        .eq('id', locationId)
        .eq('organization_id', profile.organization_id)

    if (error) return { error: error.message }

    revalidatePath('/settings')
    revalidatePath('/warehouses')
    return { success: true }
}

export async function deleteLocation(locationId: string) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    const { data: profile } = await supabase
        .from('profiles')
        .select('organization_id, role, is_super_admin')
        .eq('id', user.id)
        .single()

    if (!profile?.organization_id) return { error: 'Unauthorized' }
    if (profile.role !== 'ADMIN' && !profile.is_super_admin) {
        return { error: 'Only Admins can delete warehouses' }
    }

    // Prevent deleting default location
    const { data: location } = await supabase
        .from('locations')
        .select('is_default')
        .eq('id', locationId)
        .eq('organization_id', profile.organization_id)
        .single()

    if (!location) {
        return { error: "Warehouse not found" }
    }

    if (location?.is_default) {
        return { error: "Cannot delete the Default Warehouse." }
    }

    const { error } = await supabase
        .from('locations')
        .delete()
        .eq('id', locationId)
        .eq('organization_id', profile.organization_id)

    if (error) return { error: error.message }

    revalidatePath('/settings')
    revalidatePath('/warehouses')
    return { success: true }
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { Resend } from 'resend'

const inviteSchema = z.object({
    email: z.string().email(),
    role: z.enum(['STOREKEEPER', 'MANAGER', 'ADMIN']),
})

const resend = new Resend(process.env.RESEND_API_KEY)

export async function inviteMember(prevState: unknown, formData: FormData) {
    const supabase = await createClient()

    const email = formData.get('email') as string
    const role = formData.get('role') as 'STOREKEEPER' | 'MANAGER' | 'ADMIN'

    const validatedFields = inviteSchema.safeParse({ email, role })

    if (!validatedFields.success) {
        return { error: 'Invalid email or role' }
    }

    try {
        const { data: { user } } = await supabase.auth.getUser()
        if (!user) return { error: 'Unauthorized' }

        // 1. Check Admin Privileges
        const { data: profile } = await supabase
            .from('profiles')
            .select('*, organizations(plan_type, max_users)')
            .eq('id', user.id)
            .single()

        if (profile?.role !== 'ADMIN' && !profile?.is_super_admin) {
            return { error: 'Only Admins can invite members' }
        }

        const orgId = profile.organization_id
        // @ts-expect-error -- third-party type mismatch
        const plan = profile.organizations?.plan_type || 'FREE'
        // @ts-expect-error -- third-party type mismatch
        const maxUsers = profile.organizations?.max_users || 1

        // 2. Check User Limit
        // Count existing active profiles + pending invitations
        const { count: usersCount } = await supabase
            .from('profiles')
            .select('*', { count: 'exact', head: true })
            .eq('organization_id', orgId)

        const { count: invitesCount } = await supabase
            .from('invitations')
            .select('*', { count: 'exact', head: true })
            .eq('organization_id', orgId)
            .eq('status', 'PENDING')

        const totalUsers = (usersCount || 0) + (invitesCount || 0)

        if (totalUsers >= maxUsers) {
            // Special message for Free plan
            if (plan === 'FREE') {
                return { error: `Free Plan is limited to 1 user. Upgrade to Pro to invite your team.` }
            }
            return { error: `User limit reached (${maxUsers} users). Upgrade your plan.` }
        }

        // 3. Create Invitation
        const token = crypto.randomUUID()
        const { error: inviteError } = await supabase.from('invitations').insert({
            organization_id: orgId,
            email,
            role,
            token,
            invited_by: user.id
        })

        if (inviteError) {
            if (inviteError.code === '23505') return { error: 'This user is already invited' }
            throw inviteError
        }

        // 4. Send Email (Mock for now if Key missing, but code ready)
        if (process.env.RESEND_API_KEY) {
            await resend.emails.send({
                from: 'InvMaster <onboarding@resend.dev>',
                to: email,
                subject: 'You have been invited to join an organization',
                html: `<p>You have been invited to join <strong>Inventory App</strong>. <a href="${process.env.NEXT_PUBLIC_APP_URL}/invite/accept?token=${token}">Click here to join</a></p>`
            })
        } else {
            // Email skipped — no API key configured
        }

        revalidatePath('/settings')
        return { message: 'Invitation sent successfully' }

    } catch (error: unknown) {
        console.error('Invite Error:', error)
        return { error: error.message || 'Failed to invite user' }
    }
}

export async function removeMember(prevState: unknown, formData: FormData) {
    const supabase = await createClient()
    const userId = formData.get('userId') as string

    // Security: Only Admin of same org can remove
    try {
        const { data: { user } } = await supabase.auth.getUser()
        if (!user) return { error: 'Unauthorized' }

        const { data: adminProfile } = await supabase
            .from('profiles')
            .select('organization_id, role')
            .eq('id', user.id)
            .single()

        if (adminProfile?.role !== 'ADMIN') return { error: 'Unauthorized' }

        // Remove org_id from target user
        const { error } = await supabase
            .from('profiles')
            .update({ organization_id: null }) // Make them orphan
            .eq('id', userId)
            .eq('organization_id', adminProfile.organization_id) // Ensure same org

        if (error) throw error

        revalidatePath('/settings')
        return { message: 'Member removed' }

    } catch (error: unknown) {
        return { error: error.message }
    }
}

export async function cancelInvitation(formData: FormData) {
    const supabase = await createClient()
    const inviteId = formData.get('inviteId') as string

    try {
        const { data: { user } } = await supabase.auth.getUser()
        if (!user) return { error: 'Unauthorized' }

        const { data: adminProfile } = await supabase
            .from('profiles')
            .select('organization_id, role')
            .eq('id', user.id)
            .single()

        if (adminProfile?.role !== 'ADMIN') return { error: 'Unauthorized' }

        const { error } = await supabase
            .from('invitations')
            .delete()
            .eq('id', inviteId)
            .eq('organization_id', adminProfile.organization_id)

        if (error) throw error

        revalidatePath('/settings')
        return { message: 'Invitation cancelled' }
    } catch (_error: any) {
        return { error: 'Failed to cancel invitation' }
    }
}

