'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Plus, Loader2, ScanBarcode, ChevronsUpDown, Check } from 'lucide-react'
import { createItem } from '@/app/actions/items'
import { ITEM_CATEGORIES, ITEM_UNITS } from '@/lib/constants'
import { BarcodeScanner } from '@/components/common/BarcodeScanner'
import {
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'

interface CreateItemDialogProps {
    open?: boolean
    onOpenChange?: (open: boolean) => void
    defaultSku?: string
    defaultName?: string
    defaultCategory?: string
    defaultUnit?: string
    defaultSize?: string
    defaultColor?: string
    hideTrigger?: boolean
}

export function CreateItemDialog({
    open: controlledOpen,
    onOpenChange: controlledOnOpenChange,
    defaultSku = '',
    defaultName = '',
    defaultCategory = '',
    defaultUnit = 'pcs',
    defaultSize = '',
    defaultColor = '',
    hideTrigger = false
}: CreateItemDialogProps = {}) {
    const [internalOpen, setInternalOpen] = useState(false)
    const isControlled = controlledOpen !== undefined

    const open = isControlled ? controlledOpen : internalOpen
    const setOpen = (newOpen: boolean) => {
        if (isControlled) {
            controlledOnOpenChange?.(newOpen)
        } else {
            setInternalOpen(newOpen)
        }
    }

    const [isScanning, setIsScanning] = useState(false)
    const [sku, setSku] = useState(defaultSku)
    const [name, setName] = useState(defaultName)
    const [category, setCategory] = useState(defaultCategory)
    const [unit, setUnit] = useState(defaultUnit)
    const [size, setSize] = useState(defaultSize)
    const [color, setColor] = useState(defaultColor)

    const [isPending, startTransition] = useTransition()
    const _router = useRouter()

    // Sync state with props when dialog opens/closes
    const [prevOpen, setPrevOpen] = useState(open)
    if (open !== prevOpen) {
        setPrevOpen(open)
        if (open) {
            // Only reset from defaults if we are opening
            setSku(defaultSku)
            setName(defaultName)
            if (defaultCategory) setCategory(defaultCategory)
            if (defaultUnit) setUnit(defaultUnit)
            if (defaultSize) setSize(defaultSize)
            if (defaultColor) setColor(defaultColor)
        }
    }

    async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault()
        const formData = new FormData(event.currentTarget)

        // Ensure state values are present if user didn't type them
        if (sku && !formData.get('sku')) formData.set('sku', sku)
        if (name && !formData.get('name')) formData.set('name', name)

        // Ensure combobox values are set
        if (category) formData.set('category', category)
        if (unit) formData.set('unit', unit)

        startTransition(async () => {
            const result = await createItem({}, formData)
            if (result?.error) {
                toast.error(result.error)
            } else {
                toast.success('Item created successfully')
                setOpen(false)
                // Reset form
                setSku('')
                setName('')
            }
        })
    }

    async function fetchProductDetails(barcode: string) {
        setSku(barcode)
        toast.info('Fetching product details...')
        try {
            const response = await fetch(`https://world.openfoodfacts.org/api/v0/product/${barcode}.json`)
            const data = await response.json()

            if (data.status === 1 && data.product) {
                const productName = data.product.product_name || data.product.product_name_en
                if (productName) {
                    setName(productName)
                    toast.success('Product found: ' + productName)
                } else {
                    toast.info('Product found but no name available')
                }
            } else {
                toast.info('Product not found in database')
            }
        } catch (error) {
            console.error('Error fetching product:', error)
            toast.error('Failed to fetch product details')
        }
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            {!hideTrigger && (
                <DialogTrigger asChild>
                    <Button>
                        <Plus className="mr-2 h-4 w-4" /> Add Item
                    </Button>
                </DialogTrigger>
            )}
            <DialogContent className="sm:max-w-[425px] overflow-y-auto max-h-[90vh]">
                <DialogHeader>
                    <DialogTitle>Add New Item</DialogTitle>
                    <DialogDescription>
                        Create a new item. Free plan limited to 50 items.
                    </DialogDescription>
                </DialogHeader>
                <form onSubmit={onSubmit} className="space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="name">Name</Label>
                        <Input
                            id="name"
                            name="name"
                            placeholder="Apple"
                            required
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                        />
                    </div>
                    <div className="space-y-2">
                        <Label htmlFor="sku">SKU / Barcode</Label>
                        <div className="flex gap-2">
                            <Input
                                id="sku"
                                name="sku"
                                placeholder="APL-001"
                                required
                                value={sku}
                                onChange={(e) => setSku(e.target.value)}
                            />
                            <Button type="button" variant="outline" size="icon" onClick={() => setIsScanning(true)} title="Scan Barcode">
                                <ScanBarcode className="h-4 w-4" />
                            </Button>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2 flex flex-col">
                            <Label>Category</Label>
                            <FormCombobox
                                items={ITEM_CATEGORIES}
                                value={category}
                                onChange={setCategory}
                                placeholder="Select category"
                                allowCustom={true}
                            />
                        </div>

                        <div className="space-y-2 flex flex-col">
                            <Label>Unit</Label>
                            <FormCombobox
                                items={ITEM_UNITS}
                                value={unit}
                                onChange={setUnit}
                                placeholder="Select unit"
                            />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="min_stock">Min Stock</Label>
                            <Input id="min_stock" name="min_stock" type="number" required defaultValue={0} min={0} />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="initial_stock">Initial Stock</Label>
                            <Input id="initial_stock" name="initial_stock" type="number" defaultValue={0} min={0} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="cost_price">Cost Price (₹)</Label>
                            <Input id="cost_price" name="cost_price" type="number" step="0.01" defaultValue={0} min={0} placeholder="0.00" />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="selling_price">Selling Price (₹)</Label>
                            <Input id="selling_price" name="selling_price" type="number" step="0.01" defaultValue={0} min={0} placeholder="0.00" />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="hsn_code">HSN Code</Label>
                            <Input id="hsn_code" name="hsn_code" placeholder="e.g. 123456" />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="gst_rate">GST Rate (%)</Label>
                            <Select name="gst_rate" defaultValue="0">
                                <SelectTrigger>
                                    <SelectValue placeholder="Select GST" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="0">0% (Exempt)</SelectItem>
                                    <SelectItem value="5">5%</SelectItem>
                                    <SelectItem value="12">12%</SelectItem>
                                    <SelectItem value="18">18%</SelectItem>
                                    <SelectItem value="28">28%</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="size">Size</Label>
                            <Input id="size" name="size" placeholder="e.g. XL, 42, 10kg" value={size} onChange={(e) => setSize(e.target.value)} />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="color">Color</Label>
                            <Input id="color" name="color" placeholder="e.g. Red, Black" value={color} onChange={(e) => setColor(e.target.value)} />
                        </div>
                    </div>

                    <DialogFooter>
                        <Button type="submit" disabled={isPending}>
                            {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            Save Item
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
            <BarcodeScanner
                open={isScanning}
                onOpenChange={setIsScanning}
                onScanSuccess={(code) => fetchProductDetails(code)}
            />
        </Dialog >
    )
}

function FormCombobox({ items, value, onChange, placeholder, allowCustom = false }: {
    items: string[]
    value: string
    onChange: (val: string) => void
    placeholder: string
    allowCustom?: boolean
}) {
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")

    // Filter items based on search
    const filteredItems = search
        ? items.filter(item => item.toLowerCase().includes(search.toLowerCase()))
        : items

    // If value is custom (not in items), add it to top
    const displayItems = value && !items.includes(value)
        ? [value, ...filteredItems]
        : filteredItems

    const handleSelect = (item: string) => {
        onChange(item)
        setOpen(false)
        setSearch("")
    }

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    type="button"
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className="w-full justify-between font-normal"
                >
                    {value
                        ? value
                        : <span className="text-muted-foreground">{placeholder}</span>}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[--radix-popover-trigger-width] p-0" align="start">
                <div className="flex flex-col">
                    {/* Search Input */}
                    <div className="flex items-center border-b px-3">
                        <input
                            className="flex h-10 w-full bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground"
                            placeholder={`Search ${placeholder.toLowerCase()}...`}
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>

                    {/* Items List */}
                    <div className="max-h-[200px] overflow-auto p-1">
                        {displayItems.length === 0 && !allowCustom && (
                            <div className="py-6 text-center text-sm text-muted-foreground">
                                No results found.
                            </div>
                        )}

                        {displayItems.length === 0 && allowCustom && search && (
                            <div className="p-2">
                                <p className="text-xs text-muted-foreground mb-2">No results found.</p>
                                <Button
                                    type="button"
                                    variant="secondary"
                                    size="sm"
                                    className="w-full"
                                    onClick={() => handleSelect(search)}
                                >
                                    + Add "{search}"
                                </Button>
                            </div>
                        )}

                        {displayItems.map((item) => (
                            <div
                                key={item}
                                className={cn(
                                    "relative flex cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none hover:bg-accent hover:text-accent-foreground",
                                    value === item && "bg-accent"
                                )}
                                onClick={() => handleSelect(item)}
                            >
                                <Check
                                    className={cn(
                                        "mr-2 h-4 w-4",
                                        value === item ? "opacity-100" : "opacity-0"
                                    )}
                                />
                                {item}
                            </div>
                        ))}
                    </div>
                </div>
            </PopoverContent>
        </Popover>
    )
}

'use client'

import { useState, useRef, useTransition } from 'react'
import Papa from 'papaparse'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from '@/components/ui/dialog'
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table'
import { Input } from '@/components/ui/input'
import { Upload, AlertTriangle, CheckCircle, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { bulkCreateItems } from '@/app/actions/items'

interface CsvItem {
    name: string
    sku: string
    category: string
    unit: string
    min_stock: string
    initial_stock: string
    cost_price: string
    selling_price: string
    size: string
    color: string
}

export function CsvImporter() {
    const [open, setOpen] = useState(false)
    const [data, setData] = useState<CsvItem[]>([])
    const [fileName, setFileName] = useState('')
    const [isPending, startTransition] = useTransition()
    const fileInputRef = useRef<HTMLInputElement>(null)

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        setFileName(file.name)

        Papa.parse(file, {
            header: true,
            skipEmptyLines: true,
            transformHeader: (h: string) => h.toLowerCase().replace(/\s+/g, '_').trim(), // Normalize headers
            complete: (results: unknown) => {
                const parsedData = results.data.map((row: unknown) => ({
                    name: row.name || row.item_name || '',
                    sku: row.sku || row.barcode || '',
                    category: row.category || '',
                    unit: row.unit || 'pcs',
                    min_stock: row.min_stock || '0',
                    initial_stock: row.initial_stock || row.quantity || '0',
                    cost_price: row.cost_price || row.buying_price || '0',
                    selling_price: row.selling_price || row.price || '0',
                    size: row.size || '',
                    color: row.color || ''
                }))
                setData(parsedData)
            },
            error: (error: Error) => {
                toast.error('Failed to parse CSV: ' + error.message)
            }
        })
    }

    const updateRow = (index: number, field: keyof CsvItem, value: string) => {
        const newData = [...data]
        newData[index] = { ...newData[index], [field]: value }
        setData(newData)
    }

    const validateRow = (item: CsvItem) => {
        return !!(item.name && item.sku && item.unit)
    }

    const allValid = data.length > 0 && data.every(validateRow)

    const handleImport = () => {
        if (!allValid) {
            toast.error('Please fix invalid rows before importing.')
            return
        }

        startTransition(async () => {
            const result = await bulkCreateItems(data)
            if (result?.error) {
                toast.error(result.error)
            } else {
                toast.success(result.message)
                setOpen(false)
                setData([])
                setFileName('')
            }
        })
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button variant="outline">
                    <Upload className="mr-2 h-4 w-4" /> Import CSV
                </Button>
            </DialogTrigger>
            <DialogContent className="max-w-4xl max-h-[80vh] flex flex-col">
                <DialogHeader>
                    <DialogTitle>Import Items via CSV</DialogTitle>
                    <DialogDescription>
                        Upload a CSV file. Required columns: Name, SKU, Unit.
                        <br />
                        Supported: Category, Min Stock, Initial Stock, Cost Price, Selling Price, Size, Color.
                    </DialogDescription>
                </DialogHeader>

                <div className="flex-1 overflow-auto min-h-[200px] border rounded-md p-4">
                    {data.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center space-y-4">
                            <Input
                                ref={fileInputRef}
                                type="file"
                                accept=".csv"
                                className="hidden"
                                onChange={handleFileUpload}
                            />
                            <div className="text-center p-8 border-2 border-dashed rounded-lg cursor-pointer hover:bg-muted/50 w-full"
                                onClick={() => fileInputRef.current?.click()}>
                                <Upload className="mx-auto h-12 w-12 text-muted-foreground" />
                                <p className="mt-2 text-sm font-medium">Click to upload CSV</p>
                                <p className="text-xs text-muted-foreground mt-1">or drag and drop here</p>
                            </div>
                            <Button variant="link" onClick={() => {
                                const csvContent = "Name,SKU,Category,Unit,Min Stock,Initial Stock,Cost Price,Selling Price,Size,Color\nApple iPhone,IPH-13,Electronics,pcs,5,10,50000,60000,128GB,Midnight"
                                const blob = new Blob([csvContent], { type: 'text/csv' })
                                const url = window.URL.createObjectURL(blob)
                                const a = document.createElement('a')
                                a.href = url
                                a.download = 'sample_inventory.csv'
                                a.click()
                            }}>
                                Download Sample CSV
                            </Button>
                        </div>
                    ) : (
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead className="w-[200px]">Name *</TableHead>
                                    <TableHead className="w-[150px]">SKU *</TableHead>
                                    <TableHead className="w-[100px]">Unit *</TableHead>
                                    <TableHead>Category</TableHead>
                                    <TableHead>Stock</TableHead>
                                    <TableHead>Cost (₹)</TableHead>
                                    <TableHead>Sell (₹)</TableHead>
                                    <TableHead>Size</TableHead>
                                    <TableHead>Color</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {data.map((row, idx) => {
                                    const isValid = validateRow(row)
                                    return (
                                        <TableRow key={idx} className={isValid ? '' : 'bg-red-50 dark:bg-red-950/20'}>
                                            <TableCell>
                                                <Input
                                                    value={row.name}
                                                    onChange={(e) => updateRow(idx, 'name', e.target.value)}
                                                    className={!row.name ? 'border-red-500' : ''}
                                                    placeholder="Required"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    value={row.sku}
                                                    onChange={(e) => updateRow(idx, 'sku', e.target.value)}
                                                    className={!row.sku ? 'border-red-500' : ''}
                                                    placeholder="Required"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    value={row.unit}
                                                    onChange={(e) => updateRow(idx, 'unit', e.target.value)}
                                                    className={!row.unit ? 'border-red-500' : ''}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    value={row.category}
                                                    onChange={(e) => updateRow(idx, 'category', e.target.value)}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    type="number"
                                                    value={row.initial_stock}
                                                    onChange={(e) => updateRow(idx, 'initial_stock', e.target.value)}
                                                    className="w-20"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    type="number"
                                                    value={row.cost_price}
                                                    onChange={(e) => updateRow(idx, 'cost_price', e.target.value)}
                                                    className="w-20"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    type="number"
                                                    value={row.selling_price}
                                                    onChange={(e) => updateRow(idx, 'selling_price', e.target.value)}
                                                    className="w-20"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    value={row.size}
                                                    onChange={(e) => updateRow(idx, 'size', e.target.value)}
                                                    className="w-20"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    value={row.color}
                                                    onChange={(e) => updateRow(idx, 'color', e.target.value)}
                                                    className="w-20"
                                                />
                                            </TableCell>
                                        </TableRow>
                                    )
                                })}
                            </TableBody>
                        </Table>
                    )}
                </div>

                <DialogFooter className="mt-4">
                    {data.length > 0 && (
                        <div className="flex gap-2 w-full justify-between items-center">
                            <Button variant="ghost" onClick={() => setData([])}>
                                Clear & Upload New
                            </Button>
                            <div className="flex gap-2 items-center">
                                {!allValid && (
                                    <span className="text-sm text-red-500 flex items-center gap-1">
                                        <AlertTriangle className="h-4 w-4" />
                                        Fix invalid rows
                                    </span>
                                )}
                                <Button onClick={handleImport} disabled={!allValid || isPending}>
                                    {isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle className="mr-2 h-4 w-4" />}
                                    Import {data.length} Items
                                </Button>
                            </div>
                        </div>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

'use client'

import { Button } from '@/components/ui/button'
import { Download, Crown, Calendar } from 'lucide-react'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { useState } from 'react'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import { Label } from '@/components/ui/label'

interface ExportButtonProps {
    items: unknown[]
    isPro: boolean
}

export function ExportButton({ items, isPro }: ExportButtonProps) {
    const router = useRouter()
    const [open, setOpen] = useState(false)
    const [dateRange, setDateRange] = useState('lifetime') // lifetime, 30, 60

    const handleClick = () => {
        if (!isPro) {
            toast.error("Export is a PRO feature. Please upgrade.")
            router.push('/pricing')
            return
        }
        setOpen(true)
    }

    const executeExport = () => {
        if (!items || items.length === 0) {
            toast.error("No items to export")
            return
        }

        // Filter Items
        let filteredItems = [...items]
        const now = new Date()

        if (dateRange === '30') {
            const thirtyDaysAgo = new Date(now.setDate(now.getDate() - 30))
            filteredItems = items.filter(item => new Date(item.created_at) >= thirtyDaysAgo)
        } else if (dateRange === '60') {
            const sixtyDaysAgo = new Date(now.setDate(now.getDate() - 60))
            filteredItems = items.filter(item => new Date(item.created_at) >= sixtyDaysAgo)
        }

        if (filteredItems.length === 0) {
            toast.warning("No items found for the selected date range.")
            return
        }

        // Convert key-value pairs to CSV
        // 1. Get headers
        const headers = ['Name', 'SKU', 'Category', 'Unit', 'Current Stock', 'Min Stock', 'Cost Price', 'Selling Price', 'Size', 'Color', 'Created At']
        const csvContent = [
            headers.join(','),
            ...filteredItems.map(item => [
                `"${item.name}"`,
                `"${item.sku}"`,
                `"${item.category || ''}"`,
                `"${item.unit}"`,
                item.current_stock,
                item.min_stock,
                item.cost_price || 0,
                item.selling_price || 0,
                `"${item.size || ''}"`,
                `"${item.color || ''}"`,
                `"${item.created_at || ''}"`
            ].join(','))
        ].join('\n')

        // Create Blob and download
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
        const url = URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.setAttribute('download', `inventory_export_${dateRange}_${new Date().toISOString().slice(0, 10)}.csv`)
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)

        setOpen(false)
        toast.success(`Exported ${filteredItems.length} items`)
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button
                    variant="outline"
                    onClick={(e) => {
                        if (!isPro) {
                            e.preventDefault()
                            handleClick()
                        }
                    }}
                    className={!isPro ? "opacity-70" : "bg-white/5 border-white/10 text-slate-200 hover:bg-white/10 hover:text-white rounded-xl backdrop-blur-sm transition-all"}
                >
                    <Download className="mr-2 h-4 w-4" />
                    Export CSV
                    {!isPro && <Crown className="ml-2 h-4 w-4 text-amber-500 fill-amber-500" />}
                </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Export Inventory</DialogTitle>
                    <DialogDescription>
                        Select a date range to filter your export.
                    </DialogDescription>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                    <div className="grid grid-cols-4 items-center gap-4">
                        <Label htmlFor="range" className="text-right">
                            Range
                        </Label>
                        <Select value={dateRange} onValueChange={setDateRange}>
                            <SelectTrigger className="col-span-3">
                                <SelectValue placeholder="Select range" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="lifetime">Lifetime (All Items)</SelectItem>
                                <SelectItem value="30">Last 30 Days</SelectItem>
                                <SelectItem value="60">Last 60 Days</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </div>
                <DialogFooter>
                    <Button onClick={executeExport}>
                        <Download className="mr-2 h-4 w-4" />
                        Download CSV
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

'use client'

import { useState, useTransition, useEffect } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as z from 'zod'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog'
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Item } from '@/types'
import { recordStockMovement } from '@/app/actions/stock'
import { Loader2 } from 'lucide-react'

const formSchema = z.object({
    quantity: z.coerce.number().min(0.01, 'Quantity must be positive'),
    type: z.enum(['IN', 'OUT']),
    reason: z.string().optional(),
})

type FormValues = z.infer<typeof formSchema>

interface QuickStockDialogProps {
    item: Item
    open: boolean
    onOpenChange: (open: boolean) => void
    defaultType?: 'IN' | 'OUT'
}

export function QuickStockDialog({ item, open, onOpenChange, defaultType = 'IN' }: QuickStockDialogProps) {
    const [isPending, startTransition] = useTransition()

    const form = useForm<unknown>({
        resolver: zodResolver(formSchema),
        defaultValues: {
            quantity: 0,
            type: defaultType,
            reason: '',
        },
    })

    // Reset form when dialog opens or defaultType changes
    useEffect(() => {
        if (open) {
            form.reset({
                quantity: 0,
                type: defaultType,
                reason: '',
            })
        }
    }, [open, defaultType, form])

    async function onSubmit(values: FormValues) {
        const formData = new FormData()
        formData.append('item_id', item.id)
        formData.append('quantity', values.quantity.toString())
        formData.append('type', values.type)
        if (values.reason) formData.append('reason', values.reason)

        startTransition(async () => {
            const result = await recordStockMovement({}, formData)

            if (result.error) {
                toast.error(result.error)
            } else {
                toast.success(result.message)
                onOpenChange(false)
            }
        })
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Quick Stock Update</DialogTitle>
                    <DialogDescription>
                        Adjust stock for {item.name}. Current: {item.current_stock} {item.unit}
                    </DialogDescription>
                </DialogHeader>
                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="quantity"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Quantity</FormLabel>
                                        <FormControl>
                                            <Input type="number" step="0.01" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="type"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Type</FormLabel>
                                        <Select onValueChange={field.onChange} defaultValue={field.value} value={field.value}>
                                            <FormControl>
                                                <SelectTrigger>
                                                    <SelectValue />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                <SelectItem value="IN">IN (Add)</SelectItem>
                                                <SelectItem value="OUT">OUT (Remove)</SelectItem>
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>
                        <FormField
                            control={form.control}
                            name="reason"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Reason (Optional)</FormLabel>
                                    <FormControl>
                                        <Input placeholder="e.g., Sale, Damage, Adjustment" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <DialogFooter>
                            <Button type="submit" disabled={isPending}>
                                {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Update Stock
                            </Button>
                        </DialogFooter>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { Sidebar } from './Sidebar'
import { Topbar } from './Topbar'
import { Loader2, AlertCircle, Phone, Mail } from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { WarehouseProvider } from '@/context/WarehouseContext'
import { AiChatWidget } from '@/components/chat/AiChatWidget'

import { usePathname } from 'next/navigation'

export function AppLayout({ children }: { children: React.ReactNode }) {
    const pathname = usePathname()
    const [loading, setLoading] = useState(true)
    const [subscriptionStatus, setSubscriptionStatus] = useState<string | null>(null)
    const [isSuperAdmin, setIsSuperAdmin] = useState(false)
    const supabase = createClient()


    useEffect(() => {
        async function checkSubscription() {
            const { data: { user } } = await supabase.auth.getUser()
            if (!user) {
                setLoading(false)
                return
            }

            // Get user's profile to check if super admin and get org_id
            const { data: profile } = await supabase
                .from('profiles')
                .select('organization_id, is_super_admin')
                .eq('id', user.id)
                .single()

            if (profile?.is_super_admin) {
                setIsSuperAdmin(true)
                setSubscriptionStatus('ACTIVE') // Super admins always have access
                setLoading(false)
                return
            }

            if (!profile?.organization_id) {
                setSubscriptionStatus('NONE')
                setLoading(false)
                return
            }

            // Get organization subscription status and end date
            const { data: org } = await supabase
                .from('organizations')
                .select('subscription_status, subscription_end_date')
                .eq('id', profile.organization_id)
                .single()

            let status = org?.subscription_status || 'NONE'

            // Check for Expiry
            if ((status === 'ACTIVE' || status === 'TRIALING') && org?.subscription_end_date) {
                const expiryDate = new Date(org.subscription_end_date)
                if (expiryDate < new Date()) {
                    status = 'EXPIRED'
                }
            }

            setSubscriptionStatus(status)
            setLoading(false)
        }

        checkSubscription()
        checkSubscription()
    }, [supabase, pathname])

    // Bypassing layout for onboarding to allow full-screen design and avoid subscription checks
    if (pathname === '/onboarding') {
        return <>{children}</>
    }

    if (loading) {
        return (
            <div className="flex h-screen w-full items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
        )
    }


    return (
        <WarehouseProvider>
            <div className="flex min-h-screen bg-background">
                <Sidebar />
                <div className="flex flex-1 flex-col min-w-0 min-h-screen relative">
                    <div className="sticky top-0 z-20 w-full backdrop-blur-xl bg-background/90 border-b shadow-sm">
                        <Topbar />
                    </div>
                    <main className="flex-1 p-4 md:p-6 w-full max-w-full">
                        {children}
                    </main>
                </div>
            </div>
            <AiChatWidget />
        </WarehouseProvider>
    )
}

