    const [trialDays, setTrialDays] = useState<number | null>(null)
    const [collapsed, setCollapsed] = useState(false)
    const [mounted, setMounted] = useState(false)
    const [userProfile, setUserProfile] = useState<unknown>(null)

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect -- data fetching in effect is intentional
        setMounted(true)
        const storedCollapsed = localStorage.getItem('sidebar-collapsed')
        if (storedCollapsed) {
            setCollapsed(storedCollapsed === 'true')
        }

        async function checkRole() {
            const { data: { user } } = await supabase.auth.getUser()
            if (user) {
                const { data: profile } = await supabase
                    .from('profiles')
                    .select('*, organizations(plan_type, subscription_end_date, subscription_status)')
                    .eq('id', user.id)
                    .single()

                if (profile) {
                    setUserProfile(profile)
                    if (profile.is_super_admin) setIsSuperAdmin(true)

                    let effectivePlan = 'FREE'
                    // @ts-expect-error -- Supabase join typing
                    if (profile.organizations?.plan_type) {
                        // @ts-expect-error -- Supabase join typing
                        effectivePlan = profile.organizations.plan_type
                        // @ts-expect-error -- Supabase join typing
                        if (profile.organizations?.subscription_end_date) {
                            // @ts-expect-error -- Supabase join typing
                            const expiry = new Date(profile.organizations.subscription_end_date)
                            // @ts-expect-error -- Supabase join typing
                            if (profile.organizations.subscription_status === 'TRIALING') {
                                const days = differenceInDays(expiry, new Date())
                                setTrialDays(days >= 0 ? days + 1 : 0)
                            }
                            if (expiry < new Date()) {
                                effectivePlan = 'FREE'
                            }
                        }
                    }
                    setPlanType(effectivePlan)
                }
            }
        }
        checkRole()
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])

    const toggleCollapse = () => {
        const newState = !collapsed
        setCollapsed(newState)
        localStorage.setItem('sidebar-collapsed', String(newState))
    }

    if (!mounted) return null // Prevent hydration mismatch

    const isLocked = (item: NavItem) => item.name === 'Reports' && planType === 'FREE' && !isSuperAdmin

    return (
        <TooltipProvider delayDuration={0}>
            <div
                className={cn(
                    "hidden border-r bg-card md:flex flex-col transition-all duration-300 ease-in-out sticky top-0 h-screen shrink-0 z-40 shadow-sm",
                    collapsed ? "w-[80px]" : "w-[280px]"
                )}
            >
                {/* Toggle Button */}
                <Button
                    variant="ghost"
                    size="icon"
                    className="absolute -right-3 top-6 h-6 w-6 rounded-full border bg-background shadow-sm hover:bg-accent z-50 hidden md:flex"
                    onClick={toggleCollapse}
                >
                    {collapsed ? <ChevronRight className="h-3 w-3" /> : <ChevronLeft className="h-3 w-3" />}
                </Button>

                {/* Header */}
                <div className={cn(
                    "flex h-16 items-center border-b px-6 transition-all duration-300",
                    collapsed ? "justify-center px-2" : "justify-between"
                )}>
                    <Link href="/dashboard" className="flex items-center gap-2 overflow-hidden">
                        <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
                            <Store className="h-5 w-5 text-primary" />
                        </div>
                        {!collapsed && (
                            <div className="flex flex-col">
                                <span className="text-sm font-bold tracking-tight">Inventory</span>
                                <span className="text-[10px] text-muted-foreground uppercase tracking-wider">Management</span>
                            </div>
                        )}
                    </Link>
                </div>

                {/* Navigation */}
                <nav className="flex-1 space-y-6 overflow-y-auto py-6 px-3 custom-scrollbar">

                    {/* Trial Banner - Only show when expanded */}
                    {!collapsed && trialDays !== null && trialDays > 0 && (
                        <div className="mx-2 mb-6 rounded-xl bg-orange-500/10 p-4 border border-orange-500/10 shadow-sm relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:opacity-20 transition-opacity">
                                <Sparkles className="h-12 w-12" />
                            </div>
                            <div className="flex items-center gap-2 mb-2 relative z-10">
                                <BadgeIcon className="h-4 w-4 text-orange-600" />
                                <span className="text-xs font-bold text-orange-600 uppercase tracking-wide">Pro Trial</span>
                            </div>
                            <p className="text-xs text-muted-foreground mb-3 relative z-10 font-medium">
                                <span className="text-foreground font-bold">{trialDays} days</span> remaining in your trial.
                            </p>
                            <Button variant="default" size="sm" className="w-full h-8 text-xs bg-orange-600 hover:bg-orange-700 text-white shadow-sm border-0" asChild>
                                <Link href="/pricing">Upgrade Plan</Link>
                            </Button>
                        </div>
                    )}

                    {navGroups.map((group, groupIndex) => (
                        <div key={group.title} className="space-y-2">
                            {!collapsed && (
                                <h4 className="px-4 text-xs font-semibold text-muted-foreground/50 uppercase tracking-wider mb-2">
                                    {group.title}
                                </h4>
                            )}
                            <div className="space-y-1">
                                {group.items.map((item) => {
                                    const isActive = pathname.startsWith(item.href)
                                    const locked = isLocked(item)

                                    if (collapsed) {
                                        return (
                                            <Tooltip key={item.href}>
                                                <TooltipTrigger asChild>
                                                    <Link
                                                        href={item.href}
                                                        className={cn(
                                                            "flex h-10 w-10 items-center justify-center rounded-lg transition-all mx-auto relative group",
                                                            isActive
                                                                ? "bg-primary text-primary-foreground shadow-md shadow-primary/20"
                                                                : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
                                                        )}
                                                    >
                                                        <item.icon className="h-5 w-5" />
                                                        {item.isPro && !isActive && (
                                                            <span className="absolute -top-1 -right-1 h-2 w-2 rounded-full bg-indigo-500 ring-2 ring-background block" />
                                                        )}
                                                        {locked && <Crown className="absolute -bottom-1 -right-1 h-3 w-3 text-amber-500 fill-amber-500" />}
                                                    </Link>
                                                </TooltipTrigger>
                                                <TooltipContent side="right" className="font-medium">
                                                    {item.name}
                                                    {item.isPro && <span className="ml-2 text-xs text-indigo-400 font-bold">PRO</span>}
                                                </TooltipContent>
                                            </Tooltip>
                                        )
                                    }

                                    return (
                                        <Link
                                            key={item.href}
                                            href={item.href}
                                            className={cn(
                                                "group flex items-center justify-between rounded-lg px-4 py-2.5 text-sm font-medium transition-all duration-200 border border-transparent mx-2",
                                                isActive
                                                    ? "bg-primary/5 text-primary border-primary/10 shadow-sm"
                                                    : "text-muted-foreground hover:bg-accent hover:text-accent-foreground hover:translate-x-1"
                                            )}
                                        >
                                            <div className="flex items-center gap-3">
                                                <item.icon className={cn(
                                                    "h-4.5 w-4.5 transition-colors",
                                                    isActive ? "text-primary" : "text-muted-foreground group-hover:text-foreground"
                                                )} />
                                                <span>{item.name}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                {item.isPro && (
                                                    <span className="px-1.5 py-0.5 rounded text-[10px] font-bold bg-indigo-500/10 text-indigo-600 border border-indigo-500/20">
                                                        PRO
                                                    </span>
                                                )}
                                                {locked && <Crown className="h-3.5 w-3.5 text-amber-500 fill-amber-500/20" />}
                                            </div>
                                        </Link>
                                    )
                                })}
                            </div>
                            {/* Add Separator except for last item */}
                            {!collapsed && groupIndex < navGroups.length - 1 && (
                                <div className="px-4 py-2">
                                    <div className="h-px bg-border/50" />
                                </div>
                            )}
                        </div>
                    ))}

                    {/* Super Admin Link */}
                    {isSuperAdmin && (
                        <div className="mt-6 px-2">
                            {!collapsed && <div className="px-2 mb-2 text-xs font-semibold text-purple-600/70 uppercase tracking-wider">Administration</div>}
                            <Link
                                href="/super-admin"
                                className={cn(
                                    "group flex items-center rounded-lg px-3 py-2 text-sm font-medium transition-colors",
                                    collapsed ? "justify-center" : "justify-between",
                                    pathname.startsWith('/super-admin')
                                        ? "bg-purple-500 text-white shadow-md shadow-purple-500/20"
                                        : "bg-purple-50 text-purple-600 hover:bg-purple-100 border border-purple-100"
                                )}
                            >
                                {collapsed ? (
                                    <Lock className="h-5 w-5" />
                                ) : (
                                    <>
                                        <div className="flex items-center gap-3">
                                            <Lock className="h-4 w-4" />
                                            <span>Super Admin</span>
                                        </div>
                                    </>
                                )}
                            </Link>
                        </div>
                    )}
                </nav>

                {/* Footer User Profile */}
                <div className="p-4 border-t bg-muted/20">
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button variant="ghost" className={cn(
                                "w-full p-0 h-auto hover:bg-transparent",
                                collapsed ? "justify-center" : "justify-start"
                            )}>
                                <div className={cn(
                                    "flex items-center gap-3 w-full",
                                    collapsed ? "justify-center" : ""
                                )}>
                                    <Avatar className="h-9 w-9 border border-border shadow-sm">
                                        <AvatarImage src="" />
                                        <AvatarFallback className="bg-primary/10 text-primary font-medium text-xs">
                                            {userProfile?.full_name?.[0] || 'U'}
                                        </AvatarFallback>
                                    </Avatar>
                                    {!collapsed && (
                                        <div className="flex flex-col items-start text-left flex-1 min-w-0">
                                            <span className="text-sm font-semibold truncate w-full text-foreground/90">
                                                {userProfile?.full_name || 'User'}
                                            </span>
                                            <span className="text-xs text-muted-foreground truncate w-full">
                                                {userProfile?.role || 'Member'}
                                            </span>
                                        </div>
                                    )}
                                    {!collapsed && <MoreVertical className="h-4 w-4 text-muted-foreground" />}
                                </div>
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align={collapsed ? "center" : "end"} side={collapsed ? "right" : "top"} className="w-56" sideOffset={10}>
                            <DropdownMenuLabel>My Account</DropdownMenuLabel>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem asChild>
                                <Link href="/settings/profile" className="cursor-pointer">
                                    <Settings className="mr-2 h-4 w-4" />
                                    <span>Settings</span>
                                </Link>
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem className="text-destructive focus:text-destructive cursor-pointer" onClick={async () => {
                                await supabase.auth.signOut()
                                window.location.href = '/login'
                            }}>
                                <LogOut className="mr-2 h-4 w-4" />
                                <span>Log out</span>
                            </DropdownMenuItem>
                        </DropdownMenuContent>
                    </DropdownMenu>
                </div>
            </div>
        </TooltipProvider>
    )
}

function BadgeIcon({ className }: { className?: string }) {
    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            className={className}
        >
            <path d="M3.85 8.62a4 4 0 0 1 4.78-4.77 4 4 0 0 1 6.74 0 4 4 0 0 1 4.78 4.78 4 4 0 0 1 0 6.74 4 4 0 0 1-4.77 4.78 4 4 0 0 1-6.75 0 4 4 0 0 1-4.78-4.77 4 4 0 0 1 0-6.76Z" />
        </svg>
    )
}

'use client'

import { useState, useEffect, useTransition } from 'react'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Plus, Trash2, ShoppingCart, Loader2, Printer, Search } from 'lucide-react'
import { createInvoice } from '@/app/actions/invoices'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Item, InvoiceItem } from '@/types'
import { InvoiceTemplate } from '@/components/sales/InvoiceTemplate'
import { getWarehouseCookie } from '@/app/actions/warehouse-cookie' // Server Action

interface RecordSaleDialogProps {
    trigger?: React.ReactNode
    initialItem?: Item
    open?: boolean
    onOpenChange?: (open: boolean) => void
}

export function RecordSaleDialog({ trigger, initialItem, open: controlledOpen, onOpenChange: setControlledOpen }: RecordSaleDialogProps) {
    const [internalOpen, setInternalOpen] = useState(false)

    // Use controlled state if provided, otherwise internal
    const isControlled = controlledOpen !== undefined
    const open = isControlled ? controlledOpen : internalOpen

    const setOpen = (newOpen: boolean) => {
        if (isControlled) {
            setControlledOpen?.(newOpen)
        } else {
            setInternalOpen(newOpen)
        }
    }

    const [step, setStep] = useState<'CART' | 'DETAILS' | 'SUCCESS'>('CART')
    const [items, setItems] = useState<Item[]>([])
    const [cart, setCart] = useState<InvoiceItem[]>([])
    const [searchTerm, setSearchTerm] = useState('')
    const [isPending, startTransition] = useTransition()
    const [lastInvoiceId, setLastInvoiceId] = useState<string | null>(null)
    const [lastInvoiceData, setLastInvoiceData] = useState<unknown>(null)

    // Customer Details
    const [customerName, setCustomerName] = useState('')
    const [customerPhone, setCustomerPhone] = useState('')
    const [paymentMethod, setPaymentMethod] = useState('CASH')

    const supabase = createClient()

    // Fetch Items for Search
    useEffect(() => {
        async function fetchItems() {
            if (!open) return
            const { data: { user } } = await supabase.auth.getUser()
            if (!user) return

            const { data: profile } = await supabase
                .from('profiles')
                .select('organization_id')
                .eq('id', user.id)
                .single()

            if (profile?.organization_id) {
                const warehouseId = await getWarehouseCookie()

                // 1. Fetch ALL items for the organization
                const { data: allItems } = await supabase
                    .from('items')
                    .select('*')
                    .eq('organization_id', profile.organization_id)

                if (!allItems) {
                    setItems([])
                    return
                }

                let finalItems = allItems

                // 2. If warehouse selected, fetch specific stock
                if (warehouseId) {
                    const { data: stockData } = await supabase
                        .from('item_stock')
                        .select('item_id, quantity')
                        .eq('location_id', warehouseId)
                        .in('item_id', allItems.map(i => i.id))

                    // Map stock data to items (override current_stock)
                    finalItems = allItems.map(item => {
                        const stockEntry = stockData?.find(s => s.item_id === item.id)
                        return {
                            ...item,
                            current_stock: stockEntry ? stockEntry.quantity : 0 // Default to 0 if no record for this warehouse
                        }
                    })
                }

                // 3. Filter out items with 0 stock (Optional, or just show them as out of stock)
                setItems(finalItems)
            }
        }
        fetchItems()
    }, [open, supabase])

    // Auto-add initial item if provided
    useEffect(() => {
        if (open && initialItem && items.length > 0 && cart.length === 0) {
            const found = items.find(i => i.id === initialItem.id)
            if (found) {
                // Determine valid quantity to add (1 or 0 if OOS)
                if ((found.current_stock || 0) > 0) {
                    // eslint-disable-next-line react-hooks/set-state-in-effect -- data fetching in effect is intentional
                    setCart([{
                        item_id: found.id,
                        name: found.name,
                        quantity: 1,
                        unit_price: found.selling_price || 0,
                        total: found.selling_price || 0
                    }])
                    toast.success(`${found.name} added to cart`)
                } else {
                    toast.error(`${found.name} is out of stock`)
                }
            }
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open, items, initialItem])

    const filteredItems = items.filter(i =>
        i.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        i.sku.toLowerCase().includes(searchTerm.toLowerCase())
    )

    const addToCart = (item: Item) => {
        setCart(prev => {
            const existing = prev.find(p => p.item_id === item.id)
            if (existing) {
                if (existing.quantity >= (item.current_stock || 0)) {
                    toast.error(`Only ${item.current_stock} units available`)
                    return prev
                }
                return prev.map(p => p.item_id === item.id
                    ? { ...p, quantity: p.quantity + 1, total: (p.quantity + 1) * p.unit_price }
                    : p)
            }

            if ((item.current_stock || 0) < 1) {
                toast.error('Item is out of stock')
                return prev
            }

            return [...prev, {
                item_id: item.id,
                name: item.name,
                quantity: 1,
                unit_price: item.selling_price || 0,
                total: item.selling_price || 0
            }]
        })
        setSearchTerm('') // Clear search after adding
    }

    const removeFromCart = (itemId: string) => {
        setCart(prev => prev.filter(p => p.item_id !== itemId))
    }

    const updateQty = (itemId: string, qty: number) => {
        if (qty < 1) return

        const originalItem = items.find(i => i.id === itemId)
        if (originalItem && qty > (originalItem.current_stock || 0)) {
            toast.error(`Only ${originalItem.current_stock} units available`)
            return
        }

        setCart(prev => prev.map(p => p.item_id === itemId ? { ...p, quantity: qty, total: qty * p.unit_price } : p))
    }

    const cartTotal = cart.reduce((sum, item) => sum + item.total, 0)

    const handleCheckout = async () => {
        if (cart.length === 0) return

        const formData = new FormData()
        formData.append('customer_name', customerName)
        formData.append('customer_phone', customerPhone)
        formData.append('payment_method', paymentMethod)
        formData.append('total_amount', cartTotal.toString())
        formData.append('items', JSON.stringify(cart))

        startTransition(async () => {
            const result = await createInvoice({}, formData)
            if (result.error) {
                toast.error(result.error)
            } else {
                toast.success('Sale Recorded!')
                setLastInvoiceId(result.invoiceId)
                setLastInvoiceData({
                    id: result.invoiceId,
                    customer_name: customerName,
                    customer_phone: customerPhone,
                    items: cart,
                    total_amount: cartTotal,
                    created_at: new Date().toISOString()
                })
                setStep('SUCCESS')
            }
        })
    }

    const reset = () => {
        setCart([])
        setCustomerName('')
        setCustomerPhone('')
        setStep('CART')
        setOpen(false)
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                {trigger || (
                    <Button className="bg-green-600 hover:bg-green-700 text-white gap-2">
                        <ShoppingCart className="h-4 w-4" /> POS / New Sale
                    </Button>
                )}
            </DialogTrigger>
            <DialogContent className="sm:max-w-[800px] h-[90vh] flex flex-col p-0 gap-0">
                <DialogHeader className="p-6 pb-2">
                    <DialogTitle>
                        {step === 'CART' && 'New Sale'}
                        {step === 'DETAILS' && 'Customer Details'}
                        {step === 'SUCCESS' && 'Sale Completed'}
                    </DialogTitle>
                </DialogHeader>

                {step === 'CART' && (
                    <div className="flex flex-1 gap-4 overflow-hidden p-6 pt-0">
                        {/* Left: Search & Items */}
                        <div className="w-1/2 flex flex-col gap-4">
                            <div className="relative">
                                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                                <Input
                                    placeholder="Search item or Scan SKU..."
                                    className="pl-8"
                                    value={searchTerm}
                                    onChange={e => setSearchTerm(e.target.value)}
                                    autoFocus
                                />
                            </div>
                            <div className="flex-1 overflow-y-auto border rounded-md p-2 space-y-2">
                                {filteredItems.length === 0 && <p className="text-center text-muted-foreground py-4">No items found</p>}
                                {filteredItems.map(item => (
                                    <div key={item.id}
                                        className="flex justify-between items-center p-2 rounded-md hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer border border-transparent hover:border-slate-200"
                                        onClick={() => addToCart(item)}
                                    >
                                        <div className="truncate">
                                            <p className="font-medium truncate">{item.name}</p>
                                            <p className="text-xs text-muted-foreground">Qty: {item.current_stock}</p>
                                        </div>
                                        <div className="text-right">
                                            <p className="font-bold">₹{item.selling_price}</p>
                                            <Button size="icon" variant="ghost" className="h-6 w-6"><Plus className="h-4 w-4" /></Button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Right: Cart */}
                        <div className="w-1/2 flex flex-col border-l pl-4">
                            <h3 className="font-semibold mb-2">Current Cart</h3>
                            <div className="flex-1 overflow-y-auto space-y-3">
                                {cart.length === 0 && <div className="h-full flex items-center justify-center text-muted-foreground text-sm">Cart is empty</div>}
                                {cart.map(item => (
                                    <div key={item.item_id} className="flex justify-between items-start text-sm">
                                        <div className="flex-1">
                                            <p className="font-medium">{item.name}</p>
                                            <div className="flex items-center gap-2 mt-1">
                                                <button onClick={() => updateQty(item.item_id, item.quantity - 1)} className="px-1.5 bg-slate-200 dark:bg-slate-800 rounded">-</button>
                                                <span>{item.quantity}</span>
                                                <button onClick={() => updateQty(item.item_id, item.quantity + 1)} className="px-1.5 bg-slate-200 dark:bg-slate-800 rounded">+</button>
                                            </div>
                                        </div>
                                        <div className="text-right flex flex-col items-end">
                                            <p className="font-bold">₹{item.total}</p>
                                            <button onClick={() => removeFromCart(item.item_id)} className="text-red-500 text-xs mt-1"><Trash2 className="h-3 w-3" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <div className="mt-4 pt-4 border-t">
                                <div className="flex justify-between text-lg font-bold">
                                    <span>Total</span>
                                    <span>₹{cartTotal}</span>
                                </div>
                                <Button className="w-full mt-4" disabled={cart.length === 0} onClick={() => setStep('DETAILS')}>
                                    Proceed to Checkout
                                </Button>
                            </div>
                        </div>
                    </div>
                )}

                {step === 'DETAILS' && (
                    <div className="space-y-4 pt-4 p-6">
                        <div className="grid gap-2">
                            <Label>Payment Method</Label>
                            <div className="flex gap-2">
                                {['CASH', 'UPI', 'CARD', 'OTHER'].map(m => (
                                    <Button
                                        key={m}
                                        variant={paymentMethod === m ? 'default' : 'outline'}
                                        onClick={() => setPaymentMethod(m)}
                                        className="flex-1"
                                    >
                                        {m}
                                    </Button>
                                ))}
                            </div>
                        </div>
                        <div className="grid gap-2">
                            <Label>Customer Name (Optional)</Label>
                            <Input value={customerName} onChange={e => setCustomerName(e.target.value)} placeholder="e.g. Rahul Kumar" />
                        </div>
                        <div className="grid gap-2">
                            <Label>Phone Number (Optional)</Label>
                            <Input value={customerPhone} onChange={e => setCustomerPhone(e.target.value)} placeholder="e.g. 9876543210" />
                        </div>

                        <div className="flex justify-between gap-4 mt-8 pt-4 border-t">
                            <Button variant="outline" onClick={() => setStep('CART')}>Back</Button>
                            <Button onClick={handleCheckout} disabled={isPending} className="flex-1 bg-green-600 hover:bg-green-700">
                                {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Complete Payment (₹{cartTotal})
                            </Button>
                        </div>
                    </div>
                )}

                {step === 'SUCCESS' && (
                    <div className="flex flex-col items-center justify-center flex-1 space-y-6 pt-4 p-6 bg-slate-50 dark:bg-slate-900 overflow-hidden">

                        {/* Invoice Preview */}
                        <div className="border rounded-lg shadow-lg bg-white overflow-y-auto w-full max-w-full flex-1">
                            <div className="min-w-[600px] p-4">
                                <InvoiceTemplate invoice={lastInvoiceData} />
                            </div>
                        </div>

                        <div className="flex gap-4 w-full pt-4 border-t bg-white dark:bg-slate-950 p-4">
                            <Button className="flex-1 bg-slate-900 text-white hover:bg-slate-800" onClick={() => window.print()}>
                                <Printer className="mr-2 h-4 w-4" /> Print Receipt
                            </Button>
                            <Button className="flex-1" variant="outline" onClick={reset}>
                                New Sale
                            </Button>
                        </div>
                    </div>
                )}
            </DialogContent>
        </Dialog>
    )
}

'use client'

import { useState } from 'react'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Rocket, BarChart3, ScanBarcode, ShieldCheck, Sparkles, Check } from 'lucide-react'
import { toast } from 'sonner'
import { startFreeTrial } from '@/app/actions/subscription'
import { useRouter } from 'next/navigation'

interface TrialOfferDialogProps {
    open?: boolean
    onOpenChange?: (open: boolean) => void
    organizationId: string
    trialUsed: boolean
    planType: string
    isTrigger?: boolean
    trigger?: React.ReactNode
}

export function TrialOfferDialog({ open, onOpenChange, organizationId, trialUsed, planType, isTrigger = false, trigger }: TrialOfferDialogProps) {
    const _router = useRouter()
    const [loading, setLoading] = useState(false)
    const [internalOpen, setInternalOpen] = useState(false)

    // Controlled vs Uncontrolled logic
    const isOpen = open !== undefined ? open : internalOpen
    const setOpen = onOpenChange || setInternalOpen

    const handleStartTrial = async () => {
        if (!organizationId) {
            toast.error("Organization ID missing. Please refresh the page.")
            return
        }
        setLoading(true)
        try {
            const result = await startFreeTrial(organizationId)

            if (result.error) {
                toast.error(result.error)
            } else {
                toast.success('🎉 Welcome to Pro! 5-Day Trial Activated.')
                setOpen(false)
                // Force reload to ensure all Pro features unlock immediately
                window.location.reload()
            }
        } catch (_error) {
            toast.error('Something went wrong. Please try again.')
        } finally {
            setLoading(false)
        }
    }

    // Don't show if already pro or trial used
    const canTry = !trialUsed && planType === 'FREE'

    return (
        <Dialog open={isOpen} onOpenChange={setOpen}>
            {isTrigger && canTry && (
                <div onClick={() => setOpen(true)} className="cursor-pointer">
                    {trigger || <Button variant="default" size="sm">Start Free Trial 🚀</Button>}
                </div>
            )}

            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2 text-2xl font-bold text-primary">
                        <Sparkles className="h-6 w-6 text-yellow-500" />
                        Unlock Inventory Pro
                    </DialogTitle>
                    <DialogDescription className="text-base pt-2">
                        Experience the full power of our platform with a <strong>5-Day Free Trial</strong>. No credit card required.
                    </DialogDescription>
                </DialogHeader>

                <div className="grid gap-4 py-4">
                    <div className="grid grid-cols-1 gap-3">
                        <FeatureRow icon={<BarChart3 className="text-blue-500" />} text="Advanced Financial Analytics & KPIs" />
                        <FeatureRow icon={<ScanBarcode className="text-purple-500" />} text="Barcode Scanning App for Mobile" />
                        <FeatureRow icon={<ShieldCheck className="text-green-500" />} text="Security Audit Logs & Tracking" />
                        <FeatureRow icon={<Rocket className="text-orange-500" />} text="AI Stock Predictions & Insights" />
                    </div>
                </div>

                <DialogFooter className="flex-col sm:flex-col gap-2">
                    <Button
                        onClick={handleStartTrial}
                        disabled={loading}
                        className="w-full bg-blue-600 hover:bg-blue-700 text-white text-lg py-6 shadow-lg shadow-blue-500/20"
                    >
                        {loading ? 'Activating...' : 'Start My 5-Day Free Trial'}
                    </Button>
                    <p className="text-xs text-center text-muted-foreground mt-2">
                        Trial automatically ends after 5 days. You won't be charged.
                    </p>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

function FeatureRow({ icon, text }: { icon: React.ReactNode, text: string }) {
    return (
        <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50 border hover:bg-muted/80 transition-colors">
            <div className="h-8 w-8 rounded-full bg-background flex items-center justify-center p-1.5 shadow-sm">
                {icon}
            </div>
            <span className="font-medium text-sm">{text}</span>
            <Check className="h-4 w-4 ml-auto text-green-500" />
        </div>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { getUserTickets } from '@/app/actions/support'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Loader2, MessageSquare, Clock, CheckCircle2, AlertCircle } from 'lucide-react'
import { formatDistanceToNow } from 'date-fns'

type Ticket = {
    id: string
    subject: string
    message: string
    status: string
    created_at: string
    type: string
}

export function UserTickets() {
    const [tickets, setTickets] = useState<Ticket[]>([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        async function fetch() {
            const res = await getUserTickets()
            if (res.data) {
                setTickets(res.data as Ticket[])
            }
            setLoading(false)
        }
        fetch()
    }, [])

    if (loading) {
        return <div className="flex justify-center p-8"><Loader2 className="h-6 w-6 animate-spin text-muted-foreground" /></div>
    }

    const statusColor = (status: string) => {
        switch (status) {
            case 'OPEN': return 'bg-blue-500/10 text-blue-500 hover:bg-blue-500/20'
            case 'IN_PROGRESS': return 'bg-amber-500/10 text-amber-500 hover:bg-amber-500/20'
            case 'RESOLVED': return 'bg-green-500/10 text-green-500 hover:bg-green-500/20'
            case 'CLOSED': return 'bg-gray-500/10 text-gray-500 hover:bg-gray-500/20'
            default: return 'bg-secondary text-secondary-foreground'
        }
    }

    const typeIcon = (type: string) => {
        switch (type) {
            case 'BUG': return <AlertCircle className="h-4 w-4 text-red-500" />
            case 'FEATURE_REQUEST': return <MessageSquare className="h-4 w-4 text-purple-500" />
            default: return <MessageSquare className="h-4 w-4 text-blue-500" />
        }
    }

    return (
        <Card className="h-[600px] flex flex-col">
            <CardHeader>
                <CardTitle>My Ticket History</CardTitle>
                <CardDescription>
                    Track the status of your support requests.
                </CardDescription>
            </CardHeader>
            <CardContent className="flex-1 overflow-hidden p-0">
                <ScrollArea className="h-full px-6 pb-6">
                    <div className="space-y-4">
                        {tickets.length === 0 ? (
                            <div className="text-center py-12 text-muted-foreground space-y-2">
                                <MessageSquare className="h-10 w-10 mx-auto opacity-20" />
                                <p>No tickets found.</p>
                                <p className="text-sm">Submit one if you need help!</p>
                            </div>
                        ) : tickets.map((ticket) => (
                            <div key={ticket.id} className="flex flex-col gap-2 rounded-lg border p-4 shadow-sm hover:bg-muted/50 transition-colors">
                                <div className="flex items-start justify-between">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            {typeIcon(ticket.type)}
                                            <span className="font-semibold text-sm">{ticket.subject}</span>
                                        </div>
                                        <p className="text-xs text-muted-foreground line-clamp-1 pl-6">
                                            {ticket.message}
                                        </p>
                                    </div>
                                    <Badge className={statusColor(ticket.status)}>
                                        {ticket.status}
                                    </Badge>
                                </div>
                                <div className="flex items-center gap-4 text-xs text-muted-foreground pl-6 pt-2">
                                    <div className="flex items-center gap-1">
                                        <Clock className="h-3 w-3" />
                                        {formatDistanceToNow(new Date(ticket.created_at), { addSuffix: true })}
                                    </div>
                                    {/* Placeholder for future activity/update time */}
                                </div>
                            </div>
                        ))}
                    </div>
                </ScrollArea>
            </CardContent>
        </Card>
    )
}

'use client'

import { useState } from 'react'
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Plus, MapPin, Trash2, Edit, Store } from 'lucide-react'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { toast } from "sonner"
import { createLocation, deleteLocation, updateLocation } from '@/app/actions/locations'

interface Location {
    id: string
    name: string
    address?: string
    is_default: boolean
}

interface WarehouseListProps {
    locations: Location[]
    organizationId: string
    isPro: boolean
}

export function WarehouseList({ locations, organizationId, isPro }: WarehouseListProps) {
    const [isCreateOpen, setIsCreateOpen] = useState(false)
    const [isEditOpen, setIsEditOpen] = useState(false)
    const [isLoading, setIsLoading] = useState(false)

    // State for Create
    const [newLocation, setNewLocation] = useState({ name: '', address: '' })

    // State for Edit
    const [editingLocation, setEditingLocation] = useState<Location | null>(null)

    const handleCreate = async () => {
        if (!newLocation.name) return toast.error("Name is required")

        setIsLoading(true)
        const result = await createLocation({
            name: newLocation.name,
            address: newLocation.address,
            organizationId
        })
        setIsLoading(false)

        if (result.error) {
            toast.error(result.error)
        } else {
            toast.success("Warehouse added successfully!")
            setIsCreateOpen(false)
            setNewLocation({ name: '', address: '' })
        }
    }

    const handleEdit = async () => {
        if (!editingLocation || !editingLocation.name) return toast.error("Name is required")

        setIsLoading(true)
        const result = await updateLocation(editingLocation.id, {
            name: editingLocation.name,
            address: editingLocation.address
        })
        setIsLoading(false)

        if (result.error) {
            toast.error(result.error)
        } else {
            toast.success("Warehouse updated successfully!")
            setIsEditOpen(false)
            setEditingLocation(null)
        }
    }

    const openEditDialog = (loc: Location) => {
        setEditingLocation({ ...loc })
        setIsEditOpen(true)
    }

    const handleDelete = async (id: string) => {
        if (confirm("Are you sure? This action cannot be undone if stock is assigned.")) {
            const result = await deleteLocation(id)
            if (result.error) toast.error(result.error)
            else toast.success("Warehouse deleted")
        }
    }

    if (!isPro) {
        return (
            <div className="rounded-2xl border border-white/5 bg-white/5 backdrop-blur-sm overflow-hidden shadow-2xl p-12 text-center">
                <Store className="h-16 w-16 mx-auto text-slate-600 mb-6" />
                <h3 className="text-xl font-bold text-white mb-2">Upgrade to Multi-Warehouse</h3>
                <p className="text-slate-400 mb-8 max-w-md mx-auto">
                    Track inventory across multiple physical locations, shops, or godowns.
                </p>
                <Button asChild className="bg-indigo-600 hover:bg-indigo-700 text-white border-0 shadow-lg rounded-xl px-8">
                    <a href="/pricing">Upgrade to Pro</a>
                </Button>
            </div>
        )
    }

    return (
        <div className="rounded-2xl border border-white/5 bg-white/5 backdrop-blur-sm overflow-hidden shadow-2xl p-6">
            <div className="flex flex-row items-center justify-between mb-6">
                <div>
                    <h3 className="text-lg font-semibold text-white/90">Your Locations</h3>
                </div>
                <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                    <DialogTrigger asChild>
                        <Button className="bg-indigo-500 hover:bg-indigo-600 text-white border-0 rounded-xl shadow-lg shadow-indigo-500/20">
                            <Plus className="mr-2 h-4 w-4" /> Add Warehouse
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="bg-slate-900 border-white/10 text-white">
                        <DialogHeader>
                            <DialogTitle>Add New Warehouse</DialogTitle>
                            <DialogDescription className="text-slate-400">Create a new warehouse or store location.</DialogDescription>
                        </DialogHeader>
                        <div className="grid gap-4 py-4">
                            <div className="grid gap-2">
                                <Label htmlFor="name" className="text-slate-300">Warehouse Name</Label>
                                <Input
                                    id="name"
                                    placeholder="e.g., Downtown Store"
                                    value={newLocation.name}
                                    onChange={(e) => setNewLocation({ ...newLocation, name: e.target.value })}
                                    className="bg-white/5 border-white/10 text-white placeholder:text-slate-600"
                                />
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="address" className="text-slate-300">Address (Optional)</Label>
                                <Input
                                    id="address"
                                    placeholder="e.g., 123 Main St"
                                    value={newLocation.address}
                                    onChange={(e) => setNewLocation({ ...newLocation, address: e.target.value })}
                                    className="bg-white/5 border-white/10 text-white placeholder:text-slate-600"
                                />
                            </div>
                        </div>
                        <DialogFooter>
                            <Button variant="ghost" onClick={() => setIsCreateOpen(false)} className="text-slate-400 hover:text-white hover:bg-white/5">Cancel</Button>
                            <Button onClick={handleCreate} disabled={isLoading} className="bg-indigo-600 hover:bg-indigo-700 text-white">
                                {isLoading ? "Creating..." : "Create Warehouse"}
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            <div className="space-y-4">
                {locations.map((loc) => (
                    <div key={loc.id} className="flex items-center justify-between p-4 border border-white/5 bg-slate-900/30 rounded-xl hover:bg-white/5 transition-all duration-200 group">
                        <div className="flex items-start gap-4">
                            <div className="p-3 bg-indigo-500/10 rounded-lg border border-indigo-500/20">
                                <Store className="h-5 w-5 text-indigo-400" />
                            </div>
                            <div>
                                <h4 className="font-medium text-slate-200 group-hover:text-white transition-colors flex items-center gap-2">
                                    {loc.name}
                                    {loc.is_default && <Badge variant="secondary" className="bg-indigo-500/10 text-indigo-300 border-indigo-500/20 text-[10px] px-1.5 h-5">Default</Badge>}
                                </h4>
                                {loc.address && <p className="text-sm text-slate-500 mt-1">{loc.address}</p>}
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <Button variant="ghost" size="icon" onClick={() => openEditDialog(loc)} className="text-slate-400 hover:text-white hover:bg-white/10 rounded-lg">
                                <Edit className="h-4 w-4" />
                            </Button>
                            {!loc.is_default && (
                                <Button variant="ghost" size="icon" onClick={() => handleDelete(loc.id)} className="text-slate-400 hover:text-red-400 hover:bg-red-500/10 rounded-lg">
                                    <Trash2 className="h-4 w-4" />
                                </Button>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Dialog */}
            <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
                <DialogContent className="bg-slate-900 border-white/10 text-white">
                    <DialogHeader>
                        <DialogTitle>Edit Warehouse</DialogTitle>
                        <DialogDescription className="text-slate-400">Update warehouse details.</DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                        <div className="grid gap-2">
                            <Label htmlFor="edit-name" className="text-slate-300">Warehouse Name</Label>
                            <Input
                                id="edit-name"
                                value={editingLocation?.name || ''}
                                onChange={(e) => setEditingLocation(prev => prev ? { ...prev, name: e.target.value } : null)}
                                className="bg-white/5 border-white/10 text-white"
                            />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="edit-address" className="text-slate-300">Address (Optional)</Label>
                            <Input
                                id="edit-address"
                                value={editingLocation?.address || ''}
                                onChange={(e) => setEditingLocation(prev => prev ? { ...prev, address: e.target.value } : null)}
                                className="bg-white/5 border-white/10 text-white"
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="ghost" onClick={() => setIsEditOpen(false)} className="text-slate-400 hover:text-white hover:bg-white/5">Cancel</Button>
                        <Button onClick={handleEdit} disabled={isLoading} className="bg-indigo-600 hover:bg-indigo-700 text-white">
                            {isLoading ? "Saving..." : "Save Changes"}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    )
}

import { Resend } from 'resend'

const resend = new Resend(process.env.RESEND_API_KEY)

export async function sendLowStockAlert(
    email: string,
    itemName: string,
    currentStock: number,
    minStock: number,
    organizationName: string
) {
    if (!process.env.RESEND_API_KEY) {
        console.warn('RESEND_API_KEY is not set. Skipping email alert.')
        return
    }

    try {
        const { data, error } = await resend.emails.send({
            from: 'InvMaster Alerts <onboarding@resend.dev>', // Default Resend test domain
            to: [email],
            subject: `⚠️ Low Stock Alert: ${itemName}`,
            html: `
        <h1>Low Stock Warning</h1>
        <p><strong>Item:</strong> ${itemName}</p>
        <p><strong>Current Stock:</strong> <span style="color: red; font-weight: bold;">${currentStock}</span></p>
        <p><strong>Minimum Threshold:</strong> ${minStock}</p>
        <p><strong>Organization:</strong> ${organizationName}</p>
        <hr />
        <p>Please reorder this item soon to avoid stockouts.</p>
        <a href="${process.env.NEXT_PUBLIC_APP_URL}/dashboard">Go to Dashboard</a>
      `,
        })

        if (error) {
            console.error('Resend error:', error)
            return { success: false, error }
        } else {
            return { success: true }
        }
    } catch (err) {
        console.error('Failed to send email alert:', err)
        return { success: false, error: err }
    }
}

import { createServerClient, type CookieOptions } from '@supabase/ssr'
import { cookies } from 'next/headers'

export async function createClient() {
    const cookieStore = await cookies()

    return createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        {
            cookies: {
                getAll() {
                    return cookieStore.getAll()
                },
                setAll(cookiesToSet) {
                    try {
                        cookiesToSet.forEach(({ name, value, options }) =>
                            cookieStore.set(name, value, options)
                        )
                    } catch {
                        // The `setAll` method was called from a Server Component.
                        // This can be ignored if you have middleware refreshing
                        // user sessions.
                    }
                },
            },
        }
    )
}

import { createServerClient, type CookieOptions } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function middleware(request: NextRequest) {
    // Create a new Headers object to modify request headers
    const requestHeaders = new Headers(request.headers)
    requestHeaders.set('x-current-path', request.nextUrl.pathname)

    let response = NextResponse.next({
        request: {
            headers: requestHeaders,
        },
    })

    const supabase = createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        {
            cookies: {
                getAll() {
                    return request.cookies.getAll()
                },
                setAll(cookiesToSet) {
                    cookiesToSet.forEach(({ name, value, options }) =>
                        request.cookies.set(name, value)
                    )
                    response = NextResponse.next({
                        request,
                    })
                    cookiesToSet.forEach(({ name, value, options }) =>
                        response.cookies.set(name, value, options)
                    )
                },
            },
        }
    )

    const {
        data: { user },
    } = await supabase.auth.getUser()

    const path = request.nextUrl.pathname

    // Auth protection for dashboard and super-admin
    if (!user && (path.startsWith('/dashboard') || path.startsWith('/super-admin'))) {
        return NextResponse.redirect(new URL('/login', request.url))
    }

    // Redirect logged-in users away from login page
    if (user && path.startsWith('/login')) {
        // Optionally, we could check if they are super admin and redirect to /super-admin
        // But for now, let's default to dashboard, and dashboard can show a link to Super Admin if applicable
        return NextResponse.redirect(new URL('/dashboard', request.url))
    }

    // Redirect logged-in users to dashboard, but let guests see the landing page
    if (path === '/' && user) {
        return NextResponse.redirect(new URL('/dashboard', request.url))
    }

    return response
}

